<?php
function homeHeroCss(): string {return '.hero{isolation:isolate;background:#171217}.hero .hero-image{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;object-fit:cover!important;object-position:center 30%!important;opacity:.82;z-index:0}.hero:after{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,rgba(8,9,11,.97) 0%,rgba(8,9,11,.86) 30%,rgba(8,9,11,.48) 58%,rgba(8,9,11,.18) 100%),linear-gradient(0deg,rgba(8,9,11,.94) 0%,rgba(8,9,11,.18) 55%,rgba(8,9,11,.3) 100%)}.hero .hero-copy{position:relative;z-index:2}@media(max-width:760px){.hero .hero-image{object-position:center top!important;opacity:.76}.hero:after{background:linear-gradient(0deg,rgba(8,9,11,.98) 0%,rgba(8,9,11,.78) 38%,rgba(8,9,11,.12) 78%,rgba(8,9,11,.22) 100%)}.hero .hero-copy{min-height:430px;display:flex;flex-direction:column;justify-content:flex-end;padding:150px 24px 32px!important}}';}
function brand(array $s): string {return $s['logo']?'<img src="'.esc($s['logo']).'" alt="'.esc($s['name']).'" style="max-width:180px;max-height:40px;object-fit:contain">':'<span class="brand-mark">'.esc(mb_substr($s['name'],0,1)).'</span><span>'.esc($s['name']).'</span>';}
function footerHtml(array $s): string {$links=[];foreach(['facebook'=>'Facebook','telegram'=>'Telegram','youtube'=>'YouTube','instagram'=>'Instagram'] as $k=>$name)if(!empty($s[$k]))$links[]='<a href="'.esc($s[$k]).'" target="_blank" rel="noopener noreferrer">'.$name.'</a>';return '<footer class="site-footer"><div><a class="brand" href="/">'.brand($s).'</a><p>'.esc($s['footerText']?:$s['description']).'</p></div>'.($links?'<nav aria-label="Social links">'.implode('',$links).'</nav>':'').'<small>© '.gmdate('Y').' '.esc($s['name']).'</small></footer>';}
function brandCss(array $s): string {$critical='a,a:visited,a:hover,a:active{text-decoration:none!important}.title-page{width:min(100%,1160px)!important;margin:36px auto 72px!important;padding:0 20px!important}.title-intro{display:grid!important;grid-template-columns:minmax(150px,220px) minmax(0,1fr)!important;gap:clamp(22px,4vw,42px)!important;align-items:center!important}.title-poster{display:block;width:100%;border-radius:14px}.title-info{margin:24px 0!important;padding:clamp(22px,3vw,32px)!important;background:var(--panel)!important;border:1px solid #ffffff18!important;border-radius:16px!important}.title-backdrop{opacity:.78;filter:saturate(.85) contrast(1.08);transform:scale(1.01)}.title-visual:after{background:linear-gradient(90deg,rgba(8,9,11,.96) 0%,rgba(8,9,11,.78) 38%,rgba(8,9,11,.3) 72%,rgba(8,9,11,.55) 100%),linear-gradient(0deg,rgba(8,9,11,.96) 0%,transparent 62%,rgba(8,9,11,.25) 100%)!important}.download-choice{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:20px 0;border-bottom:1px solid #ffffff15}.download-choice small{display:block;color:#9ca5b3}.public-link{text-decoration:none!important}.report-form{display:flex;gap:8px;flex-wrap:wrap}.child-row{padding:14px 0;border-bottom:1px solid #ffffff15}@media(max-width:650px){.title-page{margin:20px auto 48px!important;padding:0 14px!important}.title-intro{grid-template-columns:100px minmax(0,1fr)!important;gap:16px!important;padding:20px 16px!important}.title-info{margin:16px 0!important;padding:20px 16px!important}.download-choice{display:block}.download-choice>a{display:block;width:100%;margin-top:16px;text-align:center}.title-visual:after{background:linear-gradient(90deg,rgba(8,9,11,.92),rgba(8,9,11,.56)),linear-gradient(0deg,rgba(8,9,11,.95),transparent 65%)!important}}@media(max-width:390px){.title-intro{grid-template-columns:1fr!important}.title-poster{max-width:130px}}';return ':root{--red:'.esc($s['accent']).';--bg:'.esc($s['background']).';--panel:'.esc($s['panel']).';--text:'.esc($s['textColor']).'}body{background:var(--bg);color:var(--text)}.primary,.az button.active{background:var(--red)}.brand-mark{background:var(--red)}[hidden]{display:none!important}'.$critical;}
function shell(array $s,string $title,string $body,string $description=''): string {return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.esc($title).' — '.esc($s['name']).'</title><meta name="description" content="'.esc($description?:$s['description']).'"><link rel="stylesheet" href="/assets/styles.css?v=20260913-4">'.($s['favicon']?'<link rel="icon" href="'.esc($s['favicon']).'">':'').'<style>'.brandCss($s).'</style></head><body><header class="topbar"><a class="brand" href="/">'.brand($s).'</a><nav class="visitor-nav" aria-label="Primary"><a href="/">Home</a><a href="/?type=movie#catalog">Movies</a><a href="/?type=series#catalog">TV Series</a><a href="/?collection=anime#catalog">Anime</a><a href="/?collection=superhero#catalog">Superhero</a></nav></header>'.$body.footerHtml($s).'<script src="/assets/ads.js" defer></script></body></html>';}
function device(): string {$ua=strtolower($_SERVER['HTTP_USER_AGENT']??'');return preg_match('/ipad|tablet/',$ua)?'tablet':(preg_match('/mobile|android|iphone/',$ua)?'mobile':'desktop');}
function adHtml(string $slot,array $s): string {if(empty($s['adsEnabled']))return '';$all=records('SELECT * FROM cv_ads WHERE slot=? AND active=1',[$slot]);$now=ms();$valid=array_values(array_filter($all,fn($a)=>in_array($a['data']['device']??'all',['all',device()],true)));$valid=array_values(array_filter($valid,fn($a)=>(empty($a['data']['start'])||$a['data']['start']<=$now)&&(empty($a['data']['end'])||$a['data']['end']>$now)));if(!$valid&&in_array($slot,['homepage-top','movie-top','gateway-top'],true))return adHtml('all-pages',$s);if(!$valid)return '';$ad=$valid[0];if(($s['adRotation']??'priority')==='priority')usort($valid,fn($a,$b)=>($b['data']['priority']??0)<=>($a['data']['priority']??0));else $ad=$valid[array_rand($valid)];return '<aside class="managed-ad"><small>ADVERTISEMENT</small><div class="ad-frame" data-ad-width="'.(int)($ad['data']['width']??0).'" data-ad-height="'.(int)($ad['data']['height']??250).'">'.$ad['data']['code'].'</div></aside>';}
function youtubeId(string $v): string {if(!$v)return '';if(preg_match('~^https://(?:www\.|m\.)?youtube\.com/(?:watch\?.*?v=|shorts/|live/|embed/)([A-Za-z0-9_-]{11})~',$v,$m)||preg_match('~^https://youtu\.be/([A-Za-z0-9_-]{11})~',$v,$m))return $m[1];return '';}
function titlePage(array $r,bool $preview=false): string {$s=site();$d=$r['data'];$children=array_filter(records('SELECT * FROM cv_catalog WHERE parent_id=? ORDER BY created_at',[$r['id']]),fn($x)=>$preview||published($x));$downloads=records('SELECT * FROM cv_downloads WHERE title_id=? AND active=1 ORDER BY created_at',[$r['id']]);$watches=rows('SELECT * FROM cv_watches WHERE title_id=? AND active=1 ORDER BY created_at',[$r['id']]);$links='';foreach($downloads as $l){$report=signToken(['purpose'=>'report','id'=>$l['id'],'exp'=>time()+3600]);$links.='<div class="download-choice"><div><strong>'.esc(implode(' · ',array_filter([$l['data']['quality']??'',$l['name']]))).'</strong><small>'.esc(implode(' · ',array_filter([$l['data']['size']??'',$l['data']['language']??'',$l['data']['format']??'']))).'</small>'.($preview?'':'<details><summary>Report broken link</summary><form class="report-form" method="post" action="/report"><input type="hidden" name="token" value="'.esc($report).'"><select name="reason"><option>Link not working</option><option>File removed</option><option>Wrong movie</option><option>Wrong quality</option><option>Other</option></select><button class="ghost">Submit report</button></form></details>').'</div>'.($preview?'<span>Download disabled in preview</span>':'<a class="primary public-link" href="/go/'.esc($l['id']).'">Download</a>').'</div>';}
 $watch='';if($watches){$buttons='';foreach($watches as $w)$buttons.='<a class="primary public-link" href="'.esc($w['url']).'" target="_blank" rel="noopener noreferrer nofollow">'.esc($w['name']).' ↗</a>';$watch='<section class="title-info watch-section"><h2>Watch online</h2><p>Choose a link to continue to an external streaming page.</p><div class="watch-actions">'.$buttons.'</div></section>';}
 $yt=youtubeId($d['trailer']??'');$trailer=$yt?'<section class="title-info trailer-section" id="trailer"><h2>Watch trailer</h2><div class="trailer-frame"><iframe src="https://www.youtube-nocookie.com/embed/'.esc($yt).'?playsinline=1" title="'.esc($r['title']).' trailer" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><p class="trailer-fallback"><a href="https://youtube.com/watch?v='.esc($yt).'" target="_blank" rel="noopener">Watch on YouTube ↗</a></p></section>':(!empty($d['trailer'])?'<p><a class="ghost public-link" href="'.esc($d['trailer']).'" target="_blank" rel="noopener">Watch trailer ↗</a></p>':'');
 $kids='';if($children){foreach($children as $c)$kids.='<div class="child-row"><a href="'.($preview?'/admin/preview/'.$c['id']:'/title/'.rawurlencode($c['slug'])).'">'.esc($c['title']).'</a></div>';$kids='<section class="title-info"><h2>'.($r['kind']==='series'?'Seasons':'Episodes').'</h2>'.$kids.'</section>';}
 $body=($preview?'<div class="title-info">Admin preview · '.esc($r['status']).' · <a href="/admin">Back to admin</a></div>':'').adHtml('movie-top',$s).'<main class="title-page"><div class="title-visual">'.(!empty($d['backdrop'])?'<img class="title-backdrop" src="'.esc($d['backdrop']).'" alt="">':'').'<div class="title-intro">'.(!empty($d['poster'])?'<img class="title-poster" src="'.esc($d['poster']).'" alt="'.esc($r['title']).' poster">':'<div></div>').'<div><p>'.esc(strtoupper($r['kind'])).'</p><h1>'.esc($r['title']).'</h1><div class="meta"><span>'.(!empty($d['rating'])?'★ '.number_format((float)$d['rating'],1):'Rating unavailable').'</span><span>'.esc($d['year']??'').'</span><span>'.(!empty($d['runtime'])?(int)$d['runtime'].' min':'').'</span></div><p>'.esc(implode(' · ',$d['genres']??[])).'</p><div class="title-actions"><a class="primary public-link" href="#downloads">View download options</a>'.($yt?'<a class="ghost public-link" href="#trailer">Watch trailer</a>':'').'</div></div></div></div><section class="title-info synopsis-section"><h2>Synopsis</h2><p>'.esc($d['overview']?:'A synopsis has not been added yet.').'</p>'.(!empty($d['director'])?'<p><b>Director / Creator:</b> '.esc($d['director']).'</p>':'').(!empty($d['cast'])?'<p><b>Cast:</b> '.esc($d['cast']).'</p>':'').'</section>'.$watch.$trailer.$kids.adHtml('before-downloads',$s).'<section class="title-info downloads-section" id="downloads"><h2>Download options</h2>'.($links?:'<p>No download links have been added.</p>').'</section></main>'.adHtml('footer',$s);return shell($s,$d['seoTitle']?:$r['title'],$body,$d['metaDescription']?:mb_substr($d['overview']??'',0,180));}
